//! Unit + differential tests for the regroup port.
//!
//! The differential test asserts byte-exact equality against reference outputs
//! from the genuine pinned stable-ts 2.19.1 (generated by
//! `validation/m4-differential/gen_regroup_fixtures.py`); the unit tests pin the
//! parser grammar, per-op semantics, sentence grouping, and the ms round trip.

use super::parser::{PunctItem, RegroupError, Rule, SUPPORTED_OPS, parse_rules};
use super::words::{RSegment, RWord, words_from_segments};
use super::{algo_from_env_or, apply, default_algo, override_algo, regroup_segments};
use crate::domain::{Millis, Segment};
use pretty_assertions::assert_eq;

fn seg(start: i64, end: i64, text: &str) -> Segment {
    Segment {
        start: Millis(start),
        end: Millis(end),
        text: text.to_string(),
        translation: String::new(),
    }
}

fn rword(text: &str, start: f64, end: f64) -> RWord {
    RWord::new(text.to_string(), start, end)
}

// ------------------------------------------------------------------ parser --

#[test]
fn parse_empty_is_no_rules() {
    assert_eq!(parse_rules("").unwrap(), vec![]);
}

#[test]
fn parse_positional_skip_of_empty_arg_keeps_default() {
    // mg=0.2++42+1 -> min_gap=0.2, max_words SKIPPED (default None),
    // max_chars=42, is_sum_max=1.
    let rules = parse_rules("mg=0.2++42+1").unwrap();
    assert_eq!(
        rules,
        vec![Rule::MergeByGap {
            min_gap: 0.2,
            max_words: None,
            max_chars: Some(42),
            is_sum_max: true,
            lock: false,
            newline: false,
        }]
    );
}

#[test]
fn parse_pair_and_str_items_in_slash_list() {
    // ".* " -> ('.', ' ') pair (has '*'); "./. " list items -> strings.
    let rules = parse_rules("sp=.* /./. /。").unwrap();
    let Rule::SplitByPunctuation { punctuation, .. } = &rules[0] else {
        panic!("expected sp");
    };
    assert_eq!(
        *punctuation,
        vec![
            PunctItem::Pair(".".to_string(), " ".to_string()),
            PunctItem::Str(".".to_string()),
            PunctItem::Str(". ".to_string()),
            PunctItem::Str("。".to_string()),
        ]
    );
}

#[test]
fn parse_bare_string_punctuation_wraps_as_single_item() {
    // "sp=, " has no '/', so str_to_valid_type returns the bare string ", ".
    let rules = parse_rules("sp=, ").unwrap();
    let Rule::SplitByPunctuation { punctuation, .. } = &rules[0] else {
        panic!("expected sp");
    };
    assert_eq!(*punctuation, vec![PunctItem::Str(", ".to_string())]);
}

#[test]
fn parse_int_vs_float_coercion_by_dot_presence() {
    // gap "0.2" -> float; "sl=42" -> int max_chars.
    let Rule::MergeByGap { min_gap, .. } = parse_rules("mg=0.2").unwrap().remove(0) else {
        panic!();
    };
    assert_eq!(min_gap, 0.2);
    let Rule::SplitByLength { max_chars, .. } = parse_rules("sl=42").unwrap().remove(0) else {
        panic!();
    };
    assert_eq!(max_chars, Some(42));
}

#[test]
fn parse_unsupported_op_names_op_and_supported_set() {
    let err = parse_rules("mg=0.2_cm=1").unwrap_err();
    assert_eq!(
        err,
        RegroupError::UnsupportedOp {
            op: "cm".to_string(),
            supported: SUPPORTED_OPS,
        }
    );
    // The rendered message must name both the op and the supported set.
    let msg = err.to_string();
    assert!(msg.contains("\"cm\""), "message names the op: {msg}");
    assert!(
        msg.contains("mg") && msg.contains("sp") && msg.contains("sl"),
        "names support: {msg}"
    );
}

#[test]
fn parse_malformed_star_pair_in_list_is_bad_args() {
    // The '*'->pair split only fires INSIDE a '/'-list; a 3-part item is
    // malformed (stable-ts would raise at unpack time).
    let err = parse_rules("sp=a*b*c/. ").unwrap_err();
    assert!(matches!(err, RegroupError::BadArgs(_)), "got {err:?}");
}

#[test]
fn parse_star_outside_slash_list_is_a_plain_string() {
    // "a*b" with no '/' is NOT a pair — it's the literal string "a*b".
    let rules = parse_rules("sp=a*b").unwrap();
    let Rule::SplitByPunctuation { punctuation, .. } = &rules[0] else {
        panic!("expected sp");
    };
    assert_eq!(*punctuation, vec![PunctItem::Str("a*b".to_string())]);
}

#[test]
fn parse_sp_without_punctuation_is_bad_args() {
    assert!(matches!(parse_rules("sp="), Err(RegroupError::BadArgs(_))));
    assert!(matches!(parse_rules("sp"), Err(RegroupError::BadArgs(_))));
}

#[test]
fn parse_sl_zero_cap_is_rejected() {
    assert!(matches!(parse_rules("sl=0"), Err(RegroupError::BadArgs(_))));
}

#[test]
fn parse_full_default_ui_string() {
    let rules = parse_rules("mg=0.2++42+1_sp=.* /./. /。/?/? /？/!/! /！/,/, _sl=42").unwrap();
    assert_eq!(rules.len(), 3);
    assert!(matches!(
        rules[0],
        Rule::MergeByGap {
            min_gap,
            max_chars: Some(42),
            is_sum_max: true,
            ..
        } if min_gap == 0.2
    ));
    assert!(matches!(rules[1], Rule::SplitByPunctuation { .. }));
    assert!(matches!(
        rules[2],
        Rule::SplitByLength {
            max_chars: Some(42),
            even_split: true,
            ..
        }
    ));
}

// -------------------------------------------------------------------- words --

#[test]
fn words_group_at_sentence_end_and_keep_trailing_group() {
    let input = [
        seg(0, 100, "Hello"),
        seg(100, 250, "world."),
        seg(900, 1100, "no"),
        seg(1100, 1300, "terminator"),
    ];
    let groups = words_from_segments(&input, None);
    assert_eq!(groups.len(), 2);
    // group 0 ends at the "world." sentence terminator.
    assert_eq!(groups[0].words.len(), 2);
    assert_eq!(groups[0].words[0].text, "Hello ");
    assert_eq!(groups[0].words[1].text, "world. ");
    // group 1 is the trailing partial group (no terminator).
    assert_eq!(groups[1].words.len(), 2);
    assert_eq!(groups[1].words[1].text, "terminator ");
}

#[test]
fn words_sentence_end_is_contains_match_anywhere() {
    // "3.14" contains '.', so SENTENCE_END matches and ends a group.
    let input = [seg(0, 100, "3.14"), seg(100, 200, "rest")];
    let groups = words_from_segments(&input, None);
    assert_eq!(groups.len(), 2);
    assert_eq!(groups[0].words[0].text, "3.14 ");
}

#[test]
fn words_cjk_uses_no_separator() {
    let input = [seg(0, 100, "世界。"), seg(100, 200, "你好")];
    let groups = words_from_segments(&input, Some("zh"));
    assert_eq!(groups[0].words[0].text, "世界。"); // no trailing space
    assert_eq!(groups[1].words[0].text, "你好");
}

#[test]
fn words_none_and_unknown_language_use_space_separator() {
    let g_none = words_from_segments(&[seg(0, 100, "hi.")], None);
    assert_eq!(g_none[0].words[0].text, "hi. ");
    let g_en = words_from_segments(&[seg(0, 100, "hi.")], Some("en"));
    assert_eq!(g_en[0].words[0].text, "hi. ");
}

// --------------------------------------------------------------------- ops ---

/// Build a one-segment `Vec<RSegment>` from `(text, start, end)` word specs.
fn one_seg(words: &[(&str, f64, f64)]) -> Vec<RSegment> {
    vec![RSegment {
        words: words.iter().map(|&(t, s, e)| rword(t, s, e)).collect(),
    }]
}

#[test]
fn merge_by_gap_merges_at_and_below_boundary_not_above() {
    // Two segments; gap == min_gap (0.2) exactly -> merge (`<=`).
    let segs = vec![
        RSegment {
            words: vec![rword("a. ", 0.0, 1.0)],
        },
        RSegment {
            words: vec![rword("b. ", 1.2, 2.0)],
        }, // gap 1.2-1.0 = 0.2
    ];
    let out = apply(&parse_rules("mg=0.2").unwrap(), segs);
    assert_eq!(out.len(), 1, "gap == min_gap merges");

    // gap just over min_gap -> no merge.
    let segs = vec![
        RSegment {
            words: vec![rword("a. ", 0.0, 1.0)],
        },
        RSegment {
            words: vec![rword("b. ", 1.3, 2.0)],
        }, // gap 0.3 > 0.2
    ];
    let out = apply(&parse_rules("mg=0.2").unwrap(), segs);
    assert_eq!(out.len(), 2, "gap > min_gap does not merge");
}

#[test]
fn merge_by_gap_is_sum_max_skips_when_sum_exceeds() {
    // Two 3-char segments, gap 0. is_sum_max with max_chars=5: sum 6 > 5 -> skip.
    let segs = vec![
        RSegment {
            words: vec![rword("abc", 0.0, 1.0)],
        },
        RSegment {
            words: vec![rword("def", 1.0, 2.0)],
        },
    ];
    let out = apply(&parse_rules("mg=0.2++5+1").unwrap(), segs);
    assert_eq!(out.len(), 2, "is_sum_max: 3+3 > 5 -> not merged");

    // With max_chars=7: sum 6 <= 7 -> merge.
    let segs = vec![
        RSegment {
            words: vec![rword("abc", 0.0, 1.0)],
        },
        RSegment {
            words: vec![rword("def", 1.0, 2.0)],
        },
    ];
    let out = apply(&parse_rules("mg=0.2++7+1").unwrap(), segs);
    assert_eq!(out.len(), 1, "is_sum_max: 3+3 <= 7 -> merged");
}

#[test]
fn merge_by_gap_non_sum_max_skips_only_when_both_exceed() {
    // Non-sum-max, max_chars=4: skip only if BOTH > 4. Here 3 and 5 -> not both
    // over -> merge.
    let segs = vec![
        RSegment {
            words: vec![rword("abc", 0.0, 1.0)],
        }, // 3
        RSegment {
            words: vec![rword("defgh", 1.0, 2.0)],
        }, // 5
    ];
    let out = apply(&parse_rules("mg=0.2++4").unwrap(), segs);
    assert_eq!(out.len(), 1, "non-sum-max: only one > max -> merged");

    // Both over 4 (5 and 5) -> skip.
    let segs = vec![
        RSegment {
            words: vec![rword("abcde", 0.0, 1.0)],
        },
        RSegment {
            words: vec![rword("fghij", 1.0, 2.0)],
        },
    ];
    let out = apply(&parse_rules("mg=0.2++4").unwrap(), segs);
    assert_eq!(out.len(), 2, "non-sum-max: both > max -> not merged");
}

#[test]
fn split_by_punctuation_str_rule_ends_with() {
    // str rule ". ": split after any word ending with ". ".
    let segs = one_seg(&[
        ("one. ", 0.0, 1.0),
        ("two ", 1.0, 2.0),
        ("three. ", 2.0, 3.0),
    ]);
    let out = apply(&parse_rules("sp=. ").unwrap(), segs);
    // words[:-1] = ["one. ", "two "]; only "one. " ends with ". " -> split at 0.
    assert_eq!(out.len(), 2);
    assert_eq!(out[0].words.len(), 1);
    assert_eq!(out[0].words[0].text, "one. ");
    assert_eq!(out[1].words.len(), 2);
}

#[test]
fn split_by_punctuation_pair_rule_ends_a_next_starts_b() {
    // Pair ('.', ' '): split between a word ending '.' and a next word starting
    // ' '. Artificial words (no trailing separator) so the pair actually fires.
    let segs = vec![RSegment {
        words: vec![
            rword("hello.", 0.0, 1.0),
            rword(" world", 1.0, 2.0),
            rword("end", 2.0, 3.0),
        ],
    }];
    let rule = Rule::SplitByPunctuation {
        punctuation: vec![PunctItem::Pair(".".into(), " ".into())],
        lock: false,
        newline: false,
        min_words: None,
        min_chars: None,
        min_dur: None,
        ignore_special_periods: false,
    };
    let out = apply(&[rule], segs);
    // "hello." ends '.', " world" starts ' ' -> split at index 0.
    assert_eq!(out.len(), 2);
    assert_eq!(out[0].words[0].text, "hello.");
    assert_eq!(out[1].words.len(), 2);
}

#[test]
fn split_by_length_even_split_two_pieces() {
    // Five 5-char words -> char_count 25 > 12 -> ceil(25/12)=3 splits.
    let segs = one_seg(&[
        ("aaaa ", 0.0, 0.5),
        ("bbbb ", 0.5, 1.0),
        ("cccc ", 1.0, 1.5),
        ("dddd ", 1.5, 2.0),
        ("eeee.", 2.0, 2.6),
    ]);
    let out = apply(&parse_rules("sl=12").unwrap(), segs);
    // Matches the `nolock-chain`/`lock-chain` fixture split geometry.
    assert_eq!(out.len(), 3);
    assert_eq!(out[0].words.len(), 2); // aaaa bbbb
    assert_eq!(out[1].words.len(), 1); // cccc
    assert_eq!(out[2].words.len(), 2); // dddd eeee.
}

#[test]
fn split_by_length_under_cap_is_no_op() {
    let segs = one_seg(&[("short ", 0.0, 1.0), ("text.", 1.0, 2.0)]);
    let out = apply(&parse_rules("sl=42").unwrap(), segs);
    assert_eq!(out.len(), 1);
}

// ------------------------------------------------------------ default_algo ---

#[test]
fn default_algo_all_three_on_matches_buzz_string() {
    let s = default_algo(
        true,
        "0.2",
        true,
        ".* /./. /。/?/? /？/!/! /！/,/, ",
        true,
        "42",
    );
    assert_eq!(s, "mg=0.2++42+1_sp=.* /./. /。/?/? /？/!/! /！/,/, _sl=42");
}

#[test]
fn default_algo_len_suffix_only_when_mg_and_sl() {
    // mg on, sl off -> no ++len+1 suffix.
    assert_eq!(default_algo(true, "0.2", false, "", false, "42"), "mg=0.2");
    // mg off, sl on -> no suffix, just sl.
    assert_eq!(default_algo(false, "0.2", false, "", true, "42"), "sl=42");
    // mg + sl, no sp.
    assert_eq!(
        default_algo(true, "0.2", false, "", true, "42"),
        "mg=0.2++42+1_sl=42"
    );
    // sp only.
    assert_eq!(default_algo(false, "", true, ",", false, ""), "sp=,");
    // sp + sl (underscore join, no mg suffix).
    assert_eq!(default_algo(false, "", true, ",", true, "42"), "sp=,_sl=42");
    // nothing selected.
    assert_eq!(default_algo(false, "", false, "", false, ""), "");
}

// ---------------------------------------------------------- env override ----

#[test]
fn override_algo_env_wins_when_set_including_empty() {
    assert_eq!(override_algo("mg=0.2".into(), None), "mg=0.2");
    assert_eq!(override_algo("mg=0.2".into(), Some("sl=70")), "sl=70");
    // Set-but-empty overrides to empty (Buzz's os.getenv default semantics).
    assert_eq!(override_algo("mg=0.2".into(), Some("")), "");
}

#[test]
fn algo_from_env_or_delegates_to_override_of_current_env() {
    // Crate forbids `unsafe`, so we don't mutate the process env; instead assert
    // the wrapper is consistent with `override_algo` applied to whatever
    // `HUMM_MERGE_REGROUP_RULE` currently is (unset in CI -> the built string).
    let env = std::env::var("HUMM_MERGE_REGROUP_RULE").ok();
    let expected = override_algo("mg=0.2".into(), env.as_deref());
    assert_eq!(algo_from_env_or("mg=0.2".into()), expected);
}

// ------------------------------------------------------------- ms round trip -

#[test]
fn ms_round_trip_truncates_toward_zero() {
    // int((29/100)*100) == 28 (fake-seconds truncation quirk). A single-segment
    // no-op regroup exposes the round trip.
    let out = regroup_segments(&[seg(29, 57, "solo")], None, "").unwrap();
    assert_eq!(out.len(), 1);
    assert_eq!(out[0].start, Millis(28));
    assert_eq!(out[0].end, Millis(56));
}

#[test]
fn regroup_empty_algo_returns_sentence_groups() {
    let out = regroup_segments(&[seg(0, 100, "a"), seg(100, 200, "b.")], None, "").unwrap();
    // One sentence group ("b." terminates); text keeps trailing separators.
    assert_eq!(out.len(), 1);
    assert_eq!(out[0].text, "a b. ");
}

#[test]
fn regroup_propagates_parse_errors() {
    assert!(regroup_segments(&[seg(0, 100, "x.")], None, "cm=1").is_err());
}

// ------------------------------------------------ differential fixtures -----

#[derive(serde::Deserialize)]
struct FixtureSeg {
    start: i64,
    end: i64,
    text: String,
}

#[derive(serde::Deserialize)]
struct Fixture {
    #[allow(dead_code)]
    name: String,
    language: Option<String>,
    algo: String,
    input: Vec<FixtureSeg>,
    expected: Vec<FixtureSeg>,
}

fn to_segments(rows: &[FixtureSeg]) -> Vec<Segment> {
    rows.iter().map(|r| seg(r.start, r.end, &r.text)).collect()
}

/// Every `crates/humm-core/tests/fixtures/regroup/*.json` fixture, generated by
/// running the genuine pinned stable-ts 2.19.1 against Buzz's exact merge call
/// pattern (`validation/m4-differential/gen_regroup_fixtures.py`).
const FIXTURES: &[(&str, &str)] = &[
    (
        "default-ui",
        include_str!("../../tests/fixtures/regroup/default-ui.json"),
    ),
    (
        "mg-only",
        include_str!("../../tests/fixtures/regroup/mg-only.json"),
    ),
    (
        "sp-only",
        include_str!("../../tests/fixtures/regroup/sp-only.json"),
    ),
    (
        "sl-only",
        include_str!("../../tests/fixtures/regroup/sl-only.json"),
    ),
    (
        "mg-sl-no-sp",
        include_str!("../../tests/fixtures/regroup/mg-sl-no-sp.json"),
    ),
    ("cjk", include_str!("../../tests/fixtures/regroup/cjk.json")),
    (
        "no-sentence-punct",
        include_str!("../../tests/fixtures/regroup/no-sentence-punct.json"),
    ),
    (
        "sl-even-multi",
        include_str!("../../tests/fixtures/regroup/sl-even-multi.json"),
    ),
    (
        "mg-is-sum-max",
        include_str!("../../tests/fixtures/regroup/mg-is-sum-max.json"),
    ),
    (
        "interior-dot-grouping",
        include_str!("../../tests/fixtures/regroup/interior-dot-grouping.json"),
    ),
    (
        "sp-comma-list",
        include_str!("../../tests/fixtures/regroup/sp-comma-list.json"),
    ),
    (
        "lock-chain",
        include_str!("../../tests/fixtures/regroup/lock-chain.json"),
    ),
    (
        "nolock-chain",
        include_str!("../../tests/fixtures/regroup/nolock-chain.json"),
    ),
    (
        "sp-newline",
        include_str!("../../tests/fixtures/regroup/sp-newline.json"),
    ),
    (
        "sp-min-chars",
        include_str!("../../tests/fixtures/regroup/sp-min-chars.json"),
    ),
    (
        "sl-maxwords",
        include_str!("../../tests/fixtures/regroup/sl-maxwords.json"),
    ),
];

#[test]
fn regroup_matches_python_reference_fixtures() {
    assert!(FIXTURES.len() >= 8, "brief requires >= 8 fixtures");

    for (name, json) in FIXTURES {
        let fx: Fixture =
            serde_json::from_str(json).unwrap_or_else(|e| panic!("fixture {name} JSON: {e}"));
        let input = to_segments(&fx.input);
        let expected = to_segments(&fx.expected);

        let actual = regroup_segments(&input, fx.language.as_deref(), &fx.algo)
            .unwrap_or_else(|e| panic!("fixture {name} regroup errored: {e:?}"));

        assert_eq!(
            actual, expected,
            "fixture {name} (algo={:?}) mismatch",
            fx.algo
        );
    }
}
